import React, { useState } from "react";
import {
  Box,
  Button,
  Grid,
  TextField,
  MenuItem,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import toastMessage from "../../utils/toastMessage";
import {
  searchBeneficiaryByMobile,
  aepsAdd,
  bankPublic,
  payoutBankDelete,
  payoutDoTransaction,
} from "../../api/login/Login";

const PAYMENT_MODES = ["IMPS", "NEFT"];

const B2BSendMoneyPage = () => {
  // Step 1: Customer search
  const [mobile, setMobile] = useState("");
  const [searchLoading, setSearchLoading] = useState(false);
  const [searched, setSearched] = useState(false);
  const [beneficiaries, setBeneficiaries] = useState([]);

  // Add Beneficiary Dialog
  const [openAddDialog, setOpenAddDialog] = useState(false);
  const [bankList, setBankList] = useState([]);
  const [addLoading, setAddLoading] = useState(false);
  const [newBeneficiary, setNewBeneficiary] = useState({
    name: "",
    account_number: "",
    confirm_account_number: "",
    ifsc: "",
    bankId: "",
    bank_proof: "",
  });

  // Send Money state (per beneficiary amount + mode)   for decision making
  const [amounts, setAmounts] = useState({});
  const [modes, setModes] = useState({});
  const [sendLoading, setSendLoading] = useState({});

  // TPIN dialog
  const [openTpin, setOpenTpin] = useState(false);
  const [tpin, setTpin] = useState("");
  const [activeBeneficiary, setActiveBeneficiary] = useState(null);

  // ---------------- Search Customer ----------------
  const handleSearch = async () => {
    if (!mobile || mobile.length < 10) {
      toastMessage(true, "Enter valid mobile number");
      return;
    }
    try {
      setSearchLoading(true);
      setSearched(false);
      const res = await searchBeneficiaryByMobile(mobile);
      if (res?.data?.error === false && res?.data?.data?.length > 0) {
        setBeneficiaries(res.data.data);
      } else {
        setBeneficiaries([]);
      }
      setSearched(true);
    } catch (error) {
      setBeneficiaries([]);
      setSearched(true);
      toastMessage(true, error?.response?.data?.message || "Search failed");
    } finally {
      setSearchLoading(false);
    }
  };

  // ---------------- Add Beneficiary ----------------
const openAddBeneficiaryDialog = async () => {
  setOpenAddDialog(true);
  setNewBeneficiary((prev) => ({ ...prev, mobile_number: mobile }));
  if (bankList.length === 0) {
    try {
      const res = await bankPublic();
      setBankList(res?.data?.data || []);
    } catch (error) {
      toastMessage(true, "Unable to load bank list");
    }
  }
};

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = () => {
      setNewBeneficiary((prev) => ({ ...prev, bank_proof: reader.result }));
    };
    reader.readAsDataURL(file);
  };

  const submitAddBeneficiary = async () => {
    const {
      name,
      account_number,
      confirm_account_number,
      ifsc,
      bankId,
    } = newBeneficiary;

    if (!name || !account_number || !confirm_account_number || !ifsc || !bankId) {
      toastMessage(true, "Please fill all required fields");
      return;
    }
    if (account_number !== confirm_account_number) {
      toastMessage(true, "Account number and confirm account number must match");
      return;
    }

    try {
      setAddLoading(true);
      const payload = {
        ...newBeneficiary,
        mobile_number: mobile,
      };
      const res = await aepsAdd(payload);
      if (res?.data?.error === false) {
        toastMessage(false, res?.data?.message || "Beneficiary added successfully");
        setOpenAddDialog(false);
        setNewBeneficiary({
          name: "",
          account_number: "",
          confirm_account_number: "",
          ifsc: "",
          bankId: "",
          bank_proof: "",
        });
        // Refresh search
        handleSearch();
      } else {
        toastMessage(true, res?.data?.message || "Failed to add beneficiary");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Failed to add beneficiary");
    } finally {
      setAddLoading(false);
    }
  };

  // ---------------- Delete Beneficiary ----------------
  const handleDelete = async (id) => {
    try {
      const res = await payoutBankDelete(id);
      if (res?.data?.error === false) {
        toastMessage(false, "Beneficiary deleted");
        handleSearch();
      } else {
        toastMessage(true, res?.data?.message || "Delete failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Delete failed");
    }
  };

  // ---------------- Send Money ----------------
  const openTpinDialog = (beneficiary) => {
    const amount = amounts[beneficiary._id];
    const mode = modes[beneficiary._id];
    if (!amount || Number(amount) <= 0) {
      toastMessage(true, "Enter valid amount");
      return;
    }
    if (!mode) {
      toastMessage(true, "Select payment mode");
      return;
    }
    setActiveBeneficiary(beneficiary);
    setOpenTpin(true);
  };

  const confirmSendMoney = async () => {
    if (!/^\d{4}$/.test(tpin)) {
      toastMessage(true, "Invalid TPIN");
      return;
    }
    const beneficiary = activeBeneficiary;
    try {
      setSendLoading((prev) => ({ ...prev, [beneficiary._id]: true }));
      const payload = {
        amount: amounts[beneficiary._id],
        benificiaryId: beneficiary._id,
        paymentMode: modes[beneficiary._id],
        tpin,
        bank_name: beneficiary.bank_name,
        account_holder_name: beneficiary.bank_account_name,
        ifsc_code: beneficiary.bank_ifsc,
        mobile_number: beneficiary.mobile_number,
        account_number: beneficiary.bank_account_number,
        remark: "B2B Transfer",
        latlong: "28.6139,77.2090", // TODO: replace with actual geolocation if available
      };
      const res = await payoutDoTransaction(payload);
      if (res?.data?.error === false) {
        toastMessage(false, res?.data?.message || "Payout Successful");
        setAmounts((prev) => ({ ...prev, [beneficiary._id]: "" }));
        setModes((prev) => ({ ...prev, [beneficiary._id]: "" }));
      } else {
        toastMessage(true, res?.data?.message || "Payout Failed");
      }
    } catch (error) {
      toastMessage(true, error?.response?.data?.message || "Server error");
    } finally {
      setSendLoading((prev) => ({ ...prev, [beneficiary._id]: false }));
      setOpenTpin(false);
      setTpin("");
      setActiveBeneficiary(null);
    }
  };

  return (
    <Box p={3} bgcolor="#fff" borderRadius={2}>
      <Typography variant="h6" mb={2}>
        B2B Send Money
      </Typography>

      {/* Customer Search */}
      <Box sx={{ display: "flex", gap: 2, alignItems: "center", mb: 3 }}>
        <TextField
          size="small"
          label="Mobile Number"
          value={mobile}
          disabled={searchLoading}
          onChange={(e) => setMobile(e.target.value)}
        />
        <Button
          variant="contained"
          onClick={handleSearch}
          disabled={searchLoading}
        >
          {searchLoading ? "Searching..." : "Search"}
        </Button>
      </Box>

      {/* Results */}
      {searched && beneficiaries.length === 0 && (
        <Box mb={3}>
          <Typography variant="body2" color="text.secondary" mb={2}>
            No beneficiary found with this mobile number.
          </Typography>
          <Button variant="contained" color="success" onClick={openAddBeneficiaryDialog}>
            + Add New Beneficiary
          </Button>
        </Box>
      )}

      {beneficiaries.length > 0 && (
        <Box>
          <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 2 }}>
            <Button variant="outlined" onClick={openAddBeneficiaryDialog}>
              + Add New Beneficiary
            </Button>
          </Box>

          {beneficiaries.map((beni) => (
            <Grid
              container
              spacing={2}
              alignItems="center"
              key={beni._id}
              sx={{
                border: "1px solid #e5e7eb",
                borderRadius: 2,
                p: 2,
                mb: 2,
              }}
            >
              <Grid item xs={12} md={3}>
                <Typography variant="subtitle2">{beni.bank_account_name}</Typography>
                <Typography variant="caption" color="text.secondary">
                  {beni.bank_name} · {beni.bank_account_number}
                </Typography>
              </Grid>

              <Grid item xs={12} md={3}>
                <TextField
                  size="small"
                  fullWidth
                  type="number"
                  label="Amount"
                  value={amounts[beni._id] || ""}
                  onChange={(e) =>
                    setAmounts((prev) => ({ ...prev, [beni._id]: e.target.value }))
                  }
                />
              </Grid>

              <Grid item xs={12} md={3}>
                <TextField
                  size="small"
                  select
                  fullWidth
                  label="Mode"
                  value={modes[beni._id] || ""}
                  onChange={(e) =>
                    setModes((prev) => ({ ...prev, [beni._id]: e.target.value }))
                  }
                >
                  {PAYMENT_MODES.map((m) => (
                    <MenuItem key={m} value={m}>
                      {m}
                    </MenuItem>
                  ))}
                </TextField>
              </Grid>

              <Grid item xs={12} md={2}>
                <Button
                  fullWidth
                  variant="contained"
                  onClick={() => openTpinDialog(beni)}
                  disabled={sendLoading[beni._id]}
                >
                  {sendLoading[beni._id] ? "..." : "Send"}
                </Button>
              </Grid>

              <Grid item xs={12} md={1}>
                <IconButton color="error" onClick={() => handleDelete(beni._id)}>
                  <DeleteIcon />
                </IconButton>
              </Grid>
            </Grid>
          ))}
        </Box>
      )}

      {/* Add Beneficiary Dialog */}
      <Dialog open={openAddDialog} onClose={() => setOpenAddDialog(false)} fullWidth maxWidth="sm">
        <DialogTitle>Add New Beneficiary</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} mt={0.5}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Account Holder Name"
                value={newBeneficiary.name}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({ ...prev, name: e.target.value }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Account Number"
                value={newBeneficiary.account_number}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    account_number: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Confirm Account Number"
                value={newBeneficiary.confirm_account_number}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    confirm_account_number: e.target.value,
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="IFSC Code"
                value={newBeneficiary.ifsc}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({
                    ...prev,
                    ifsc: e.target.value.toUpperCase(),
                  }))
                }
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                select
                fullWidth
                label="Select Bank"
                value={newBeneficiary.bankId}
                onChange={(e) =>
                  setNewBeneficiary((prev) => ({ ...prev, bankId: e.target.value }))
                }
              >
                {bankList.map((bank) => (
                  <MenuItem key={bank._id} value={bank._id}>
                    {bank.bank_name}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12}>
              <Button variant="outlined" component="label">
                Upload Bank Proof
                <input type="file" hidden accept="image/*,.pdf" onChange={handleFileChange} />
              </Button>
              {newBeneficiary.bank_proof && (
                <Typography variant="caption" color="success.main" sx={{ ml: 2 }}>
                  ✔ File attached
                </Typography>
              )}
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenAddDialog(false)} disabled={addLoading}>
            Cancel
          </Button>
          <Button variant="contained" onClick={submitAddBeneficiary} disabled={addLoading}>
            {addLoading ? "Adding..." : "Add Beneficiary"}
          </Button>
        </DialogActions>
      </Dialog>

      {/* TPIN Dialog */}
      <Dialog open={openTpin} onClose={() => setOpenTpin(false)}>
        <DialogTitle align="center">Enter TPIN</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            type="password"
            value={tpin}
            inputProps={{ maxLength: 4 }}
            onChange={(e) => /^\d{0,4}$/.test(e.target.value) && setTpin(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setOpenTpin(false)}>Cancel</Button>
          <Button onClick={confirmSendMoney}>Confirm</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default B2BSendMoneyPage;